#include "RtspPipeline.h"
#include <iostream>
RtspPipeline::RtspPipeline(const EnvConfig &c):config_(c){}
RtspPipeline::~RtspPipeline(){stop();}
GstFlowReturn RtspPipeline::sample(GstAppSink *sink,gpointer data){auto*s=static_cast<RtspPipeline*>(data); if(auto*x=gst_app_sink_pull_sample(sink)){++s->frames_; gst_sample_unref(x);} return GST_FLOW_OK;}
gboolean RtspPipeline::bus(GstBus*,GstMessage*m,gpointer data){auto*s=static_cast<RtspPipeline*>(data); if(GST_MESSAGE_TYPE(m)==GST_MESSAGE_ERROR){GError*e=nullptr;gchar*d=nullptr;gst_message_parse_error(m,&e,&d);std::cerr<<"GStreamer error: "<<(e?e->message:"unknown")<<std::endl;if(d)g_free(d);if(e)g_error_free(e);if(s->loop_)g_main_loop_quit(s->loop_);}else if(GST_MESSAGE_TYPE(m)==GST_MESSAGE_EOS&&s->loop_)g_main_loop_quit(s->loop_);return G_SOURCE_CONTINUE;}
bool RtspPipeline::start(){if(config_.rtspUrl.empty()){std::cerr<<"RTSP_URL is empty"<<std::endl;return false;} const auto d="rtspsrc location=\""+config_.rtspUrl+"\" protocols=tcp latency="+std::to_string(config_.latencyMs)+" ! rtph264depay ! h264parse ! avdec_h264 ! videoconvert ! video/x-raw,format=BGR,width=320,height=240 ! appsink name=sink emit-signals=true sync=false max-buffers=1 drop=true"; GError*e=nullptr; pipeline_=gst_parse_launch(d.c_str(),&e); if(!pipeline_){std::cerr<<"Cannot create GStreamer pipeline: "<<(e?e->message:"unknown")<<std::endl;if(e)g_error_free(e);return false;} auto*sink=gst_bin_get_by_name(GST_BIN(pipeline_),"sink"); g_signal_connect(sink,"new-sample",G_CALLBACK(&RtspPipeline::sample),this);gst_object_unref(sink);auto*b=gst_element_get_bus(pipeline_);gst_bus_add_watch(b,&RtspPipeline::bus,this);gst_object_unref(b);loop_=g_main_loop_new(nullptr,false);gst_element_set_state(pipeline_,GST_STATE_PLAYING);return true;}
void RtspPipeline::run(){if(loop_)g_main_loop_run(loop_);}
void RtspPipeline::stop(){if(pipeline_){gst_element_set_state(pipeline_,GST_STATE_NULL);gst_object_unref(pipeline_);pipeline_=nullptr;}if(loop_){g_main_loop_quit(loop_);g_main_loop_unref(loop_);loop_=nullptr;}}
